using System.Windows;
using System.Windows.Controls;
using ReviveOS.Browser;
namespace ReviveOS.UI;
public sealed class ChromeBoostDialog:Window {
 readonly StackPanel choices=new();readonly TextBox log=new(){IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=190,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(6)};readonly List<(CheckBox Box,ChromeTweak Tweak)> items=[];bool busy;CancellationTokenSource? measurement;
 public ChromeBoostDialog(ChromeOptimizer optimizer){Title="Chrome Boost — local + remoto opcional";Width=820;Height=740;var panel=new StackPanel{Margin=new Thickness(12)};Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(new TextBlock{Text="Abertura do Chrome depende do HD/CPU/RAM locais. Estas opções reduzem trabalho ou isolam um perfil leve; não prometem tempo de abertura. Nenhum cache, senha, cookie ou favorito do perfil original é apagado. Políticas podem mostrar a indicação de navegador gerenciado; restauração remove apenas o que foi registrado.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(6)});panel.Children.Add(choices);
  foreach(var t in ChromePolicyBackend.Catalog){var check=new CheckBox{Content=t.Name,IsChecked=false,Margin=new Thickness(6)};choices.Children.Add(check);choices.Children.Add(new TextBlock{Text=t.Benefit+"\nRisco: "+t.Risk,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(24,0,6,8)});items.Add((check,t));}
  var actions=new WrapPanel();panel.Children.Add(actions);panel.Children.Add(log);
  Button Add(string text,Func<Task<string>> action){var b=new Button{Content=text,Margin=new Thickness(4),Padding=new Thickness(8)};b.Click+=async(_,_)=>{if(busy)return;busy=true;log.Text="Executando…";try{log.Text=await action();}catch(Exception e){log.Text=e.Message;}finally{busy=false;}};actions.Children.Add(b);return b;}
  Add("Aplicar selecionados",async()=>{var selected=items.Where(x=>x.Box.IsChecked==true).ToArray();if(selected.Length==0)return "Selecione um ajuste e leia seus riscos.";if(MessageBox.Show(string.Join("\n",selected.Select(x=>x.Tweak.Name+": "+x.Tweak.Risk))+"\nGravar políticas com backup? Valide depois em chrome://policy; aceitação depende da versão/ambiente.","Chrome Boost",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return "Nenhuma alteração aplicada.";try{await optimizer.Apply(selected.Select(x=>x.Tweak.Id));}catch{await optimizer.Restore();throw;}return "Registro gravado e verificado. Reabra Chrome normalmente e confira chrome://policy. Aceitação pelo navegador e ganhos ainda precisam ser verificados.";});
  Add("Restaurar políticas e atalho",async()=>{var errors=new List<Exception>();try{await optimizer.Restore();}catch(Exception e){errors.Add(e);}try{await ChromeShortcut.Restore();}catch(Exception e){errors.Add(e);}if(errors.Count>0)throw new AggregateException(errors);return "Configurações e atalho registrados restaurados. Perfil leve preservado para não apagar seus dados.";});
  Add("Abrir Chrome habitual",()=>{ChromeRuntime.Open();return Task.FromResult("Solicitação de abertura enviada ao Chrome instalado.");});
  Add("Abrir perfil leve separado",()=>{ChromeRuntime.Open(true,"chrome://newtab/");return Task.FromResult("Perfil separado aberto. Primeiro uso pode ser mais lento. Seus favoritos, sessões e extensões originais continuam no perfil habitual.");});
  Add("Criar atalho de perfil leve",async()=>{await ChromeShortcut.Create();return "Atalho criado na área de trabalho, sem substituir o original. O perfil separado pode conter dados pessoais após uso e não será apagado por restauração.";});
  Add("Medir abertura habitual",()=>Measure(false));Add("Medir abertura do perfil leve",()=>Measure(true));var cancel=new Button{Content="Cancelar medição",Margin=new Thickness(4),Padding=new Thickness(8)};cancel.Click+=(_,_)=>measurement?.Cancel();actions.Children.Add(cancel);
  foreach(var (label,url) in new[]{("Conferir políticas","chrome://policy/"),("Configurações de memória","chrome://settings/performance"),("Abas na inicialização","chrome://settings/onStartup"),("Revisar extensões","chrome://extensions/")})Add(label,()=>{ChromeRuntime.Open(false,url);return Task.FromResult("Página interna aberta no Chrome. Não alteramos suas extensões ou abas automaticamente.");});
  Add("Navegador remoto experimental",()=>{if(MessageBox.Show("Abrir Browser.lol para navegação de páginas públicas? É serviço externo, com anúncios/limites e possível CAPTCHA. Não é Chrome pessoal permanente. Não compartilha seu perfil local nem garante sessão disponível ou velocidade. Nada será contratado e não há reinício automático de sessões.","Navegação remota",MessageBoxButton.YesNo)==MessageBoxResult.Yes)System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("https://browser.lol/en/create"){UseShellExecute=true});return Task.FromResult("A opção remota é experimental e independente da abertura local. Respeite os limites do provedor e encerre a sessão após uso.");});
  Closing+=(_,e)=>e.Cancel=busy;
 }
 async Task<string> Measure(bool light){measurement=new();try{return System.Text.Json.JsonSerializer.Serialize(await ChromeRuntime.MeasureLaunch(light,measurement.Token),ReviveOS.Core.State.Json);}finally{measurement.Dispose();measurement=null;}}
}
